import type { Q } from "../types";

export const electrical2: Q[] = [
  // ---- Signals & systems ----
  { t: "Convolution and the impulse response", p: "Why does the impulse response completely characterise a linear time-invariant system?", d: 2, tp: "signals-systems", i: "Any input can be written as a weighted sum of shifted impulses, and for an LTI system each impulse produces a shifted, scaled copy of the impulse response h(t). By linearity and time invariance, the output is the sum of those responses, which is the convolution y = x * h. So h determines the output for every input, and its Fourier or Laplace transform gives the frequency response.", c: ["Inputs decompose into shifted impulses", "Linearity and time invariance give superposition of shifted responses", "Output is the convolution of x with h", "Transform of h gives the frequency response"], k: ["Convolution in time becomes multiplication in frequency", "Causality means h(t) = 0 for t < 0"], m: ["Applying convolution to nonlinear systems"] },
  { t: "Fourier series versus Fourier transform", p: "When do you use a Fourier series and when a Fourier transform, and what does each tell you?", d: 1, tp: "signals-systems", i: "A Fourier series represents a periodic signal as a sum of harmonics at multiples of the fundamental, giving discrete line spectra. The Fourier transform applies to aperiodic (finite energy) signals, giving a continuous spectrum. Both show how signal energy is distributed across frequency, so they guide filter design, bandwidth estimation and modulation choices.", c: ["Fourier series for periodic signals gives discrete harmonics", "Fourier transform for aperiodic signals gives a continuous spectrum", "Both show frequency content", "Used for filtering and bandwidth decisions"], k: ["Square waves contain only odd harmonics", "Time limiting a signal spreads its spectrum"], m: ["Applying a series to non-periodic signals"] },
  { t: "Sampling theorem and reconstruction", p: "State the Nyquist sampling theorem and describe what an ideal reconstruction filter does.", d: 2, tp: "signals-systems", i: "A band-limited signal with highest frequency f_max can be perfectly reconstructed from samples taken at a rate above 2·f_max. Reconstruction passes the sample impulses through an ideal low-pass filter at half the sample rate, which interpolates with sinc functions. Real systems use a practical filter, a zero-order hold followed by smoothing, and anti-alias filters before sampling since frequency content above half the sample rate folds back.", c: ["Sample at more than twice the highest frequency", "Ideal low-pass reconstruction with sinc interpolation", "Anti-alias filtering before sampling", "Real systems use zero-order hold and smoothing"], k: ["Aliasing is irreversible after sampling", "Oversampling eases filter requirements"], m: ["Sampling at exactly twice the frequency without margin"] },
  { t: "FIR versus IIR filters", p: "Compare FIR and IIR digital filters on stability, phase, computational cost and design.", d: 2, tp: "signals-systems", tp2: "embedded-systems", i: "FIR filters use only past inputs, are always stable, and can have exactly linear phase, but need many taps for sharp transitions. IIR filters use feedback, achieving sharp responses with far fewer coefficients, but can be unstable, have nonlinear phase and are sensitive to coefficient quantisation, especially in high orders, so they are implemented as cascaded second-order sections.", c: ["FIR is always stable with linear phase possible", "FIR needs many taps for sharp cutoff", "IIR is efficient but can be unstable with nonlinear phase", "IIR implemented as biquad sections"], k: ["Linear phase preserves waveform shape", "Fixed-point quantisation affects IIR more"], m: ["Using a high-order direct-form IIR in fixed point"] },
  { t: "Fast Fourier transform and spectral leakage", p: "Why does windowing matter when taking an FFT of a finite signal segment?", d: 2, tp: "signals-systems", i: "The FFT assumes the captured segment repeats periodically, so if it does not contain an integer number of cycles, the discontinuity at the edges smears energy across bins, called spectral leakage. A window tapers the ends to reduce leakage at the cost of wider main lobe, so choice trades frequency resolution against amplitude accuracy and sidelobe suppression: rectangular is narrow but leaky, Hann is a good general choice, flat-top gives accurate amplitude.", c: ["FFT assumes periodic repetition of the segment", "Non-integer cycles cause leakage", "Windows reduce leakage but widen the main lobe", "Hann for general use and flat-top for amplitude accuracy"], k: ["Resolution is the sample rate divided by the record length", "Zero padding interpolates but does not add resolution"], m: ["Reading peak amplitudes from an unwindowed FFT with leakage"] },
  { t: "Stability of discrete-time systems", p: "How do you judge stability of a digital filter from its transfer function?", d: 2, tp: "signals-systems", tp2: "control-theory", i: "A causal discrete-time LTI system is bounded-input bounded-output stable if all poles of H(z) lie inside the unit circle. Poles on the circle give marginal stability, such as oscillators, and outside means growth. Zeros do not affect stability. Quantised coefficients can move poles, so margins matter, particularly for high-order direct forms.", c: ["Poles inside the unit circle for stability", "Poles on the circle are marginal", "Zeros do not affect stability", "Coefficient quantisation can move poles"], k: ["Discrete poles map from s-plane poles via z = e^(sT)", "Cascade second-order sections for robustness"], m: ["Checking zeros instead of poles"] },
  { t: "Correlation and matched filtering", p: "How does a matched filter maximise signal-to-noise ratio, and where is it used?", d: 3, tp: "signals-systems", tp2: "communications", i: "A filter whose impulse response is the time-reversed known signal, h(t) = s(T − t), maximises output SNR at the sampling instant for white noise, equal to 2E/N0, where E is signal energy. It is equivalent to correlating the received signal with the template. Radar pulse compression, digital communications receivers and sonar use it to detect known waveforms in noise.", c: ["Impulse response is the time-reversed signal", "Maximises SNR for white noise", "Equivalent to correlation with the template", "Used in radar, communications and sonar"], k: ["SNR depends on energy, not shape", "Sampling at the correct instant is crucial"], m: ["Thinking a narrower filter always gives higher SNR"] },
  { t: "Quantisation noise and effective number of bits", p: "How much SNR does an ideal N-bit converter provide, and what degrades it in practice?", d: 2, tp: "signals-systems", tp2: "analog-electronics", i: "For a full-scale sine wave, ideal quantisation noise gives SNR ≈ 6.02N + 1.76 dB, so each bit adds about 6 dB. Real converters add thermal noise, clock jitter, nonlinearity and reference noise, so the effective number of bits is lower, computed from measured SINAD as (SINAD − 1.76)/6.02. Oversampling and averaging improve SNR by about 3 dB per doubling for white noise.", c: ["SNR ≈ 6.02N + 1.76 dB", "About 6 dB per bit", "Noise, jitter and nonlinearity reduce ENOB", "Oversampling improves SNR"], k: ["Dither can linearise quantisation error", "Jitter limits high-frequency SNR"], m: ["Assuming the datasheet bit count equals real resolution"] },
  { t: "Phase delay versus group delay", p: "What is group delay, and why does a filter with nonlinear phase distort pulses?", d: 3, tp: "signals-systems", i: "Group delay is the negative derivative of phase with respect to angular frequency, the delay of a narrowband packet's envelope. If phase is linear in frequency, group delay is constant and all components arrive together, preserving waveform shape. With nonlinear phase, different frequencies are delayed by different amounts, so edges and pulses smear or ring. Bessel and linear-phase FIR designs are chosen where waveform fidelity matters.", c: ["Group delay is −dφ/dω", "Constant group delay preserves shape", "Nonlinear phase disperses frequency components", "Bessel and linear-phase FIR filters preserve pulses"], k: ["Audio and data pulses care about phase differently", "Phase linearity trades off with sharpness"], m: ["Looking only at magnitude response"] },
  { t: "Laplace transform and poles", p: "What do the pole locations in the s-plane tell you about a system's time response?", d: 2, tp: "signals-systems", tp2: "control-theory", i: "Poles in the left half-plane give decaying exponentials, so a stable system. Real poles give pure exponential decay, with faster decay farther left. Complex-conjugate pairs give oscillation at the imaginary part's frequency with decay set by the real part. Poles on the imaginary axis are marginally stable, and right-half-plane poles give growing responses. Dominant poles nearest the axis shape the overall response.", c: ["Left half-plane poles mean decaying, stable response", "Complex poles give oscillation", "Real part sets decay rate and imaginary part sets frequency", "Right-half-plane poles grow"], k: ["Dominant poles control the response", "Zeros shape overshoot and sign of initial response"], m: ["Ignoring pole-zero cancellation limits"] },
  // ---- Electromagnetics ----
  { t: "Transmission line reflections and termination", p: "Why do signals reflect on a transmission line, and how does termination prevent it?", d: 2, tp: "electromagnetics", tp2: "hardware-debug", i: "A signal sees the line's characteristic impedance Z0; at a boundary where the load differs, the reflection coefficient Γ = (Z_L − Z0)/(Z_L + Z0) reflects part of the wave. Reflections create ringing and false edges on fast digital lines. Terminating with a resistor equal to Z0 (series at the source or parallel at the load) absorbs the wave, giving Γ = 0. Lines need treating as transmission lines when delay is a significant fraction of the rise time.", c: ["Characteristic impedance Z0", "Reflection coefficient (Z_L − Z0)/(Z_L + Z0)", "Termination equal to Z0 removes reflections", "Matters when line delay is comparable to the rise time"], k: ["Series termination suits point-to-point; parallel suits multi-drop", "Impedance discontinuities include vias and connectors"], m: ["Treating all traces as ideal wires"] },
  { t: "Skin effect and its practical consequences", p: "What is the skin effect and how does it affect conductor and PCB design at high frequency?", d: 2, tp: "electromagnetics", i: "At high frequency, alternating current crowds toward the conductor surface, with the penetration depth δ = √(2/(ωμσ)) shrinking as frequency rises, so resistance increases with the square root of frequency. Consequences are higher loss in RF conductors, the benefit of plated surfaces and Litz wire in magnetics, and the need to consider surface roughness in high-speed PCBs.", c: ["Current concentrates near the surface at high frequency", "Skin depth falls with frequency", "AC resistance rises with the square root of frequency", "Litz wire and plating mitigate loss"], k: ["Copper at 1 GHz has a skin depth of about 2 µm", "Proximity effect adds to loss in windings"], m: ["Using DC resistance for RF loss estimates"] },
  { t: "Faraday's law and inductive coupling", p: "Use Faraday's law to explain how loop area affects noise pickup, and what layout practices reduce it.", d: 2, tp: "electromagnetics", tp2: "hardware-debug", i: "A time-varying magnetic flux through a loop induces a voltage equal to −dΦ/dt, proportional to loop area and field rate of change. Large loops formed by a signal and its return path pick up more interference and also radiate more. Reduce area by routing signals close to their return paths, using twisted pairs, solid ground planes beneath signal traces and shielded cables.", c: ["Induced voltage −dΦ/dt", "Proportional to loop area", "Keep signal and return close together", "Twisted pairs, ground planes and shielding"], k: ["Return current follows the path of least impedance, under the trace at high frequency", "Differential pairs cancel common-mode pickup"], m: ["Ignoring the return path"] },
  { t: "Antenna gain, directivity and effective area", p: "How are antenna gain and effective aperture related, and why do higher frequency links often use dishes?", d: 3, tp: "electromagnetics", tp2: "communications", i: "Gain G = 4π·A_eff/λ² links antenna gain to effective aperture A_eff and wavelength. For a fixed physical size, gain rises with frequency squared, so small dishes provide narrow, high-gain beams at microwave frequencies. Directivity is the pattern's concentration of radiated power, and gain includes efficiency losses. High gain needs accurate pointing because the beam is narrow.", c: ["G = 4π A_eff/λ²", "Gain rises with frequency for a fixed size", "Gain equals directivity times efficiency", "Narrow beams need accurate pointing"], k: ["Path loss grows with frequency, partly offset by aperture gain", "Beamwidth is roughly λ over the aperture size"], m: ["Thinking antennas amplify power"] },
  { t: "EMC: radiated emissions and immunity design", p: "Outline practical steps to pass radiated emissions and immunity testing for an electronic product.", d: 2, tp: "electromagnetics", tp2: "hardware-debug", i: "Reduce emissions at the source by slowing unnecessary edge rates, minimising loop areas, using solid ground planes, filtering power and I/O with ferrites and capacitors, spread-spectrum clocking, and shielding enclosures with good seams and cable shield terminations. Immunity needs filtering and protection (TVS diodes), robust grounding, firmware error handling and layout that avoids coupling. Pre-compliance scans catch problems before the formal lab test.", c: ["Reduce edge rates and loop areas", "Ground planes, filtering and ferrites", "Shielding and cable terminations", "Pre-compliance testing"], k: ["Cables act as the main radiating antennas", "Fix at the source before adding shielding"], m: ["Leaving EMC to the end of the project"] },
  { t: "Maxwell's equations in engineering terms", p: "Summarise what each of Maxwell's four equations says in practical terms.", d: 2, tp: "electromagnetics", i: "Gauss's law relates electric flux to enclosed charge, so charges are sources of electric fields. Gauss's law for magnetism says there are no magnetic monopoles, so field lines close on themselves. Faraday's law says changing magnetic flux induces electric fields, the basis of transformers and generators. Ampère-Maxwell says currents and changing electric fields create magnetic fields, including displacement current, which allows wave propagation.", c: ["Gauss: charges source electric fields", "No magnetic monopoles", "Faraday: changing B induces E", "Ampère-Maxwell: current and changing E create B"], k: ["Coupled changing E and B fields make electromagnetic waves", "Displacement current lets capacitors conduct in circuits"], m: ["Ignoring displacement current"] },
  { t: "Characteristic impedance of a PCB trace", p: "What determines the characteristic impedance of a microstrip trace and how do you control it in a board?", d: 2, tp: "electromagnetics", tp2: "hardware-debug", i: "It depends on trace width, copper thickness, dielectric thickness to the reference plane and dielectric constant: wider traces or thinner dielectric lower the impedance. Designers pick the stack-up, then set width to hit targets such as 50 Ω single-ended or 100 Ω differential, and the fabricator tunes for process tolerance. Keep a continuous reference plane to maintain impedance.", c: ["Depends on width, dielectric height and permittivity", "Wider trace or thinner dielectric lowers impedance", "Target values 50 Ω single-ended and 100 Ω differential", "Continuous reference plane required"], k: ["Fabricators control impedance within a tolerance", "Return path discontinuities act as impedance changes"], m: ["Choosing width without checking the stack-up"] },
  { t: "Near-field versus far-field radiation", p: "What distinguishes near field from far field and why does it matter for EMC measurements and antenna design?", d: 3, tp: "electromagnetics", i: "Close to a source, the reactive near field stores energy and the electric and magnetic components have no fixed relationship, with strength falling rapidly with distance. Beyond roughly λ/2π or several wavelengths for large apertures, the radiating far field forms, with E and H in fixed ratio equal to the free-space impedance (377 Ω) and power falling as 1/r². Test setups and antenna patterns are defined in the far field; near-field probes diagnose sources.", c: ["Near field is reactive with energy stored", "Far field is radiating with E/H = 377 Ω", "Far field power falls as 1/r²", "Patterns are measured in the far field"], k: ["Transition distance depends on wavelength and aperture", "Magnetic loops sense near-field sources"], m: ["Applying far-field formulas inside the near field"] },
  { t: "Wave propagation in waveguides versus free space", p: "Why do waveguides have a cutoff frequency?", d: 3, tp: "electromagnetics", tp2: "communications", i: "A waveguide supports modes only if the wavelength is short enough to fit the cross-section; below the cutoff frequency (f_c = c/2a for the dominant rectangular TE10 mode of width a) waves decay evanescently instead of propagating. Above cutoff, propagation is dispersive, with guide wavelength longer than the free-space value. Waveguides give very low loss at microwave frequencies and high power handling.", c: ["Modes need wavelength compatible with the cross-section", "Cutoff frequency for the dominant mode f_c = c/2a", "Below cutoff waves decay evanescently", "Low loss and high power at microwave frequencies"], k: ["Dispersion alters group and phase velocity", "Dimensions set the usable band"], m: ["Assuming waveguides pass DC or low frequencies"] },
  { t: "Capacitance, dielectrics and fringing", p: "How would you estimate the capacitance of a parallel-plate structure and when does fringing matter?", d: 1, tp: "electromagnetics", tp2: "circuit-analysis", i: "C = ε₀·ε_r·A/d for plates of area A separated by distance d with dielectric constant ε_r. The formula assumes a uniform field between plates. When the gap is not small compared with plate dimensions, fringe fields add capacitance beyond the estimate, which matters for small PCB pads, sensors and gap capacitors. Dielectric breakdown limits maximum voltage per unit thickness.", c: ["C = ε A / d", "Uniform field assumption", "Fringing adds capacitance for large gaps", "Dielectric breakdown limits voltage"], k: ["Dielectric constant changes with frequency and temperature", "Stored energy is ½CV²"], m: ["Using the ideal formula for wide gaps"] },
  // ---- Control theory ----
  { t: "Root locus intuition", p: "What does the root locus show, and how does adding a pole or zero change closed-loop behaviour?", d: 3, tp: "control-theory", i: "The root locus plots closed-loop pole locations as loop gain varies from zero to infinity, starting at open-loop poles and ending at zeros. It shows where the system goes unstable and how damping and speed change with gain. Adding poles pulls branches toward the right, reducing stability, while adding zeros pulls them to the left, increasing stability and damping.", c: ["Closed-loop poles versus gain", "Branches start at poles and end at zeros", "Added poles move the locus right", "Added zeros move the locus left"], k: ["Crossing the imaginary axis sets the gain limit", "Compensators reshape the locus"], m: ["Thinking adding a pole always improves stability"] },
  { t: "Steady-state error and system type", p: "How does the number of integrators in the loop determine steady-state error for step and ramp inputs?", d: 2, tp: "control-theory", i: "A type 0 system (no integrators) has finite error for a step and infinite error for a ramp. Type 1 has zero error for a step and finite constant error for a ramp. Type 2 has zero error for steps and ramps and finite error for parabolas. The error constants Kp, Kv and Ka measure these, and adding an integrator improves steady-state accuracy at the cost of phase lag.", c: ["Type 0 finite step error and infinite ramp error", "Type 1 zero step error and finite ramp error", "Type 2 zero error for ramps", "Integrators improve accuracy but cost phase margin"], k: ["Error constants come from the low-frequency gain", "Integrators can cause windup"], m: ["Assuming a higher gain alone removes steady-state error"] },
  { t: "Lead and lag compensators", p: "Compare a lead compensator and a lag compensator and when you would use each.", d: 2, tp: "control-theory", i: "A lead compensator adds phase advance near the crossover frequency, increasing phase margin and speeding the response, at the cost of higher high-frequency gain and noise sensitivity. A lag compensator raises low-frequency gain to cut steady-state error without moving the crossover much, at the cost of phase lag and a slower tail. Use lead for stability and speed, lag for accuracy, and lead-lag for both.", c: ["Lead adds phase near crossover", "Lead increases noise sensitivity", "Lag raises low-frequency gain for accuracy", "Lead-lag combines both"], k: ["Placement of the pole and zero relative to crossover matters", "PD is an ideal lead and PI an ideal lag"], m: ["Using lag compensation to speed up a slow system"] },
  { t: "Gain and phase margins from Nyquist", p: "How does the Nyquist criterion determine closed-loop stability, and what do margins mean physically?", d: 3, tp: "control-theory", i: "The Nyquist plot of the open-loop transfer function encircles the critical point −1 a number of times related to unstable open-loop poles, and the closed loop is stable if encirclements equal the number of open-loop right-half-plane poles (counterclockwise). The gain margin is the factor by which gain could rise before the plot hits −1, and the phase margin is the extra phase lag tolerable at unity gain, so they measure robustness to gain error and delay.", c: ["Encirclements of −1 relate to unstable poles", "Stable if encirclements equal open-loop RHP poles", "Gain margin is tolerable gain increase", "Phase margin is tolerable extra phase lag"], k: ["Margins measure distance from −1", "Time delay erodes phase margin"], m: ["Checking only the gain margin"] },
  { t: "State-space representation and controllability", p: "What does controllability mean, and how would you test it for a linear system?", d: 3, tp: "control-theory", i: "A system is controllable if inputs can move the state from any initial value to any final value in finite time. For x' = Ax + Bu, build the controllability matrix [B AB A²B ... A^(n−1)B]; the system is controllable if it has full rank n. Uncontrollable modes cannot be moved by feedback, so state feedback pole placement requires controllability, with observability needed for estimators.", c: ["Reach any state with the input", "Controllability matrix [B AB ... A^(n−1)B]", "Full rank means controllable", "Pole placement and observers need controllability and observability"], k: ["Dual concept is observability", "Practical controllability also depends on actuator limits"], m: ["Assuming every mode can be moved by the input"] },
  { t: "PID in discrete time and derivative filtering", p: "What implementation details matter when you code a PID controller in a microcontroller?", d: 2, tp: "control-theory", tp2: "embedded-systems", i: "Use a fixed sample period, compute the derivative on the measurement rather than the error to avoid kicks from setpoint changes, and low-pass filter it to reduce noise. Add anti-windup by clamping or back-calculating the integral when the output saturates, bumpless transfer when switching modes, and output limits. Scale and saturate fixed-point maths carefully to prevent overflow.", c: ["Fixed sample time", "Derivative on measurement with filtering", "Anti-windup", "Bumpless transfer and output limits"], k: ["Jitter in the sampling period degrades behaviour", "Integer overflow causes dramatic faults"], m: ["Differentiating the raw setpoint step"] },
  { t: "Disturbance rejection and sensitivity function", p: "What does the sensitivity function S = 1/(1+L) tell you about disturbance rejection and noise?", d: 3, tp: "control-theory", i: "S is the transfer function from output disturbance to output: where |L| is large, |S| is small and disturbances are rejected. T = L/(1+L), the complementary sensitivity, shows how sensor noise reaches the output, and S + T = 1, so you cannot have both small everywhere. Good designs make L large at low frequency (rejection) and small at high frequency (noise attenuation), and the peak of |S| relates to robustness.", c: ["S = 1/(1+L) maps output disturbances to output", "Large loop gain gives small S", "T handles noise and S + T = 1", "Peak of |S| indicates robustness"], k: ["Waterbed effect limits improvements", "Loop shaping balances rejection and noise"], m: ["Expecting good rejection and noise filtering at the same frequency"] },
  { t: "Cascade control for a temperature loop", p: "Why does cascade control outperform a single loop for something like a heated jacket reactor?", d: 2, tp: "control-theory", tp2: "process-control", i: "An inner fast loop controls a quickly responding secondary variable (jacket temperature), rejecting disturbances such as coolant supply changes before they affect the slow primary variable (reactor temperature), while the outer loop sets the inner setpoint. The result is faster disturbance rejection and less sensitivity to actuator nonlinearity. The inner loop must be several times faster than the outer loop.", c: ["Inner fast loop on a secondary variable", "Outer loop sets the inner setpoint", "Inner loop rejects disturbances early", "Inner loop several times faster than the outer"], k: ["Requires a measurable intermediate variable", "Tuning proceeds from inner to outer loop"], m: ["Tuning both loops at the same speed"] },
  { t: "Time delay in feedback loops", p: "Why is dead time hard for PID control and what are strategies to handle it?", d: 3, tp: "control-theory", tp2: "process-control", i: "A pure delay adds phase lag proportional to frequency without reducing gain, so achievable bandwidth is limited to roughly the inverse of the delay, and high gain leads to oscillation. Strategies include lowering gain and integral action, a Smith predictor that uses a model to cancel the delay in the loop, feedforward from measurable disturbances, and reducing the delay at its physical source with sensor placement.", c: ["Delay adds phase lag without reducing gain", "Bandwidth limited by the inverse of the delay", "Smith predictor compensates with a model", "Reduce delay physically and use feedforward"], k: ["Model mismatch weakens the Smith predictor", "Detuned controllers are common practice"], m: ["Raising gain to speed up a delayed process"] },
  { t: "Observer design and Kalman filtering relation", p: "What is a state observer, and how does a Kalman filter differ from a Luenberger observer?", d: 3, tp: "control-theory", tp2: "gnc", i: "An observer reconstructs unmeasured states by running a model of the plant and correcting it with the measured output error through a gain L. A Luenberger observer picks L to place observer poles for fast convergence, while a Kalman filter picks L optimally from noise statistics, balancing trust in the model and measurements. The result is minimum variance estimation for linear Gaussian systems.", c: ["Observer reconstructs states from the model and measurement error", "Luenberger places observer poles", "Kalman filter chooses the gain from noise statistics", "Minimum variance for linear Gaussian systems"], k: ["Separation principle allows independent controller and observer design", "Faster observers amplify measurement noise"], m: ["Making the observer as fast as possible"] },
  { t: "Actuator saturation and rate limits in control design", p: "How do actuator limits change closed-loop behaviour, and what design responses are used?", d: 2, tp: "control-theory", tp2: "mechatronics-controls", i: "Saturation clips the command so effective gain falls with large errors, which can slow response, cause limit cycles and make integrators wind up. Rate limits add phase lag. Responses include anti-windup, command shaping and reference trajectories that stay within limits, increasing actuator capability, and designing the controller with realistic constraints, or using model predictive control.", c: ["Saturation reduces effective gain", "Windup and limit cycles can result", "Rate limits add phase lag", "Anti-windup and reference shaping"], k: ["Linear analysis fails at large signals", "MPC handles constraints explicitly"], m: ["Ignoring actuator limits in linear design"] },
  // ---- Power systems ----
  { t: "Why transmission uses high voltage", p: "Why does the grid transmit power at very high voltage, and what is the trade-off?", d: 1, tp: "power-systems", i: "For a given power P = VI, raising voltage lowers current, and resistive loss I²R falls with the square of current, so losses and conductor cross-section shrink dramatically. Costs rise for insulation, tower clearance and transformers at higher voltage, and corona and safety limit the choice. So voltage is selected by distance and power level, with step-down transformers at the load end.", c: ["P = VI so higher voltage means lower current", "Loss I²R falls with the square of current", "Higher voltage needs more insulation and clearance", "Voltage chosen by distance and power"], k: ["Transformers make AC voltage change easy", "HVDC avoids reactive losses on long lines"], m: ["Thinking higher voltage increases losses"] },
  { t: "Per-unit system in power analysis", p: "Why do power engineers use a per-unit system, and how do you convert a transformer impedance between bases?", d: 2, tp: "power-systems", i: "Per-unit values divide quantities by chosen base values, so transformer ratios disappear and typical equipment impedances fall in a narrow range, making comparisons and network calculations simpler. To change base, Z_pu,new = Z_pu,old × (S_base,new / S_base,old) × (V_base,old / V_base,new)². Voltage and power bases are chosen once for the system, with current and impedance bases derived.", c: ["Quantities divided by base values", "Transformer turns ratios disappear", "Impedances fall in typical ranges", "Base conversion formula uses power and voltage squared"], k: ["Choose one power base for the whole system", "Voltage bases follow transformer ratios"], m: ["Mixing quantities with different bases"] },
  { t: "Reactive power and voltage control", p: "How does reactive power affect system voltage, and what devices control it?", d: 2, tp: "power-systems", i: "Inductive loads and lines absorb reactive power, which causes voltage drop along the network, while capacitors and overexcited generators supply it, raising voltage. Because reactive power does not travel far efficiently, it is controlled locally using shunt capacitors and reactors, tap-changing transformers, synchronous condensers and power electronics such as STATCOMs. Generators' automatic voltage regulators adjust excitation.", c: ["Inductive loads absorb reactive power and depress voltage", "Capacitors supply reactive power", "Local control is needed", "Capacitors, tap changers, STATCOMs and condensers"], k: ["Reactive power flow causes loss without delivering real power", "Low voltage with high reactive demand risks collapse"], m: ["Thinking real power alone sets voltage"] },
  { t: "Protective relaying: overcurrent and distance protection", p: "Describe how overcurrent and distance relays detect faults and why coordination matters.", d: 3, tp: "power-systems", i: "Overcurrent relays operate when current exceeds a pickup value, with inverse-time curves that trip faster for larger currents and are graded between upstream and downstream devices so the nearest breaker clears the fault first. Distance relays measure impedance (voltage over current) and trip when it indicates a fault within a set fraction of the line, giving selectivity independent of fault level. Coordination limits outages to the smallest possible area.", c: ["Overcurrent relays trip above pickup with inverse-time curves", "Grading provides selectivity", "Distance relays measure impedance to the fault", "Coordination limits outage area"], k: ["Speed versus selectivity trade-off", "Backup protection covers failures of primary devices"], m: ["Setting all relays to trip at the same time"] },
  { t: "Synchronous generator operation and stability", p: "What is the swing equation, and what does it say about transient stability?", d: 3, tp: "power-systems", tp2: "control-theory", i: "The swing equation, (2H/ω_s)·d²δ/dt² = P_m − P_e, relates rotor angle acceleration to the imbalance between mechanical input and electrical output. After a fault, electrical output drops, the rotor accelerates and the angle advances; if clearing is fast enough, the equal-area criterion shows the machine can decelerate and return to synchronism, otherwise it loses synchronism. Fast fault clearing, reducing power transfer and high inertia improve stability.", c: ["Swing equation links angle acceleration to power imbalance", "Faults reduce electrical output so the rotor accelerates", "Equal-area criterion judges stability", "Fast clearing and high inertia help"], k: ["Inertia constant H measures stored energy", "Renewable low-inertia grids face faster dynamics"], m: ["Assuming the machine always recovers from a fault"] },
  { t: "Induction motor torque-speed behaviour", p: "Explain slip and why an induction motor's rotor must run slower than synchronous speed.", d: 2, tp: "power-systems", tp2: "mechatronics-controls", i: "The stator creates a rotating field at synchronous speed. Rotor currents are induced only if the rotor moves relative to the field, so the rotor runs slightly slower, with slip s = (n_s − n)/n_s typically 1 to 5 percent at full load. Torque rises with slip up to a peak (breakdown torque) and falls beyond it, and starting torque and current are high, hence soft starters and variable-frequency drives.", c: ["Rotor induced currents need relative motion", "Slip s = (ns − n)/ns", "Torque peaks at breakdown torque", "Starting currents are high; use soft starters or drives"], k: ["Rotor resistance shapes the torque curve", "Synchronous speed is 120f/p"], m: ["Thinking an induction motor can reach synchronous speed under load"] },
  { t: "Harmonics in power systems", p: "Where do harmonics come from, and what problems and remedies are common?", d: 2, tp: "power-systems", tp2: "power-electronics", i: "Nonlinear loads such as rectifiers, variable-speed drives and LED drivers draw non-sinusoidal current, producing harmonic currents at multiples of the line frequency. They heat transformers and neutrals (triplen harmonics add in the neutral), cause voltage distortion, resonance with capacitors and nuisance trips. Remedies include passive or active filters, line reactors, multi-pulse rectifiers, active front ends and standards such as IEEE 519.", c: ["Nonlinear loads draw non-sinusoidal current", "Heating of transformers and neutral conductors", "Resonance with capacitors", "Filters, reactors and multi-pulse or active rectifiers"], k: ["Total harmonic distortion measures severity", "Source impedance determines voltage distortion"], m: ["Ignoring neutral loading from triplen harmonics"] },
  { t: "Smart grid and renewable integration challenges", p: "What technical problems arise when connecting large amounts of wind and solar to the grid?", d: 2, tp: "power-systems", i: "Output is variable and uncertain, so balancing needs flexible generation, storage and forecasting. Inverter-based sources provide little inertia, so frequency changes faster after disturbances, and low short-circuit strength weakens voltage stability and protection. Reverse power flow on distribution feeders challenges voltage regulation and protection. Solutions include grid-forming inverters, storage, demand response, grid-code ride-through and upgraded protection.", c: ["Variability and forecasting needs", "Low inertia from inverter-based sources", "Weak grids and protection issues", "Storage, grid-forming inverters and demand response"], k: ["Frequency stability depends on fast response", "Distribution networks were designed for one-way flow"], m: ["Treating renewable generation as dispatchable"] },
  { t: "Transformer losses and efficiency", p: "Name the two main transformer losses and when a transformer is most efficient.", d: 2, tp: "power-systems", i: "Core (iron) losses come from hysteresis and eddy currents, are roughly constant whenever the transformer is energised, and depend on voltage and frequency. Copper losses from I²R in windings vary with the square of load. Maximum efficiency occurs when copper loss equals core loss, usually at 50 to 70 percent of rated load for distribution transformers, which are often lightly loaded for much of the day.", c: ["Core loss from hysteresis and eddy currents is roughly constant", "Copper loss varies with the square of load current", "Peak efficiency when copper loss equals core loss", "Distribution units peak below full load"], k: ["Laminated or amorphous cores reduce eddy loss", "Efficiency standards target no-load loss"], m: ["Assuming the highest efficiency is at full load"] },
  { t: "Ground faults and grounding systems", p: "Why is system grounding important, and how do solid, resistance and ungrounded systems differ in fault behaviour?", d: 2, tp: "power-systems", i: "Grounding controls fault current and voltage rise on healthy phases and enables protection to detect faults. Solidly grounded systems produce large fault currents that trip protection quickly but cause damage and touch-voltage hazards. Resistance grounding limits ground fault current, reducing damage and allowing continued operation for a time. Ungrounded systems have tiny first-fault current but risk transient overvoltage and are harder to locate faults on.", c: ["Grounding controls fault current and overvoltage", "Solid grounding gives large current and fast tripping", "Resistance grounding limits damage", "Ungrounded systems risk overvoltages and hard fault location"], k: ["Safety touch voltages depend on fault current and impedance", "Industrial plants often use resistance grounding"], m: ["Assuming grounding is only for personnel safety"] },
  // ---- Communications ----
  { t: "Shannon capacity and what limits data rate", p: "State the Shannon-Hartley capacity formula and explain how bandwidth and SNR trade off.", d: 2, tp: "communications", i: "C = B·log₂(1 + SNR) gives the maximum error-free bit rate over a channel with bandwidth B and signal-to-noise ratio SNR. Capacity grows linearly with bandwidth but only logarithmically with SNR, so doubling bandwidth at fixed noise density helps more than doubling power at high SNR. Real systems approach the limit using strong error-correcting codes, with a remaining gap.", c: ["C = B log2(1 + SNR)", "Linear in bandwidth", "Logarithmic in SNR", "Coding approaches but never exceeds the limit"], k: ["Noise power grows with bandwidth", "Spectral efficiency is bits per second per hertz"], m: ["Believing more power always scales data rate linearly"] },
  { t: "Digital modulation: BPSK, QPSK and QAM trade-offs", p: "Compare BPSK, QPSK and 64-QAM on spectral efficiency and noise tolerance.", d: 2, tp: "communications", i: "BPSK sends one bit per symbol and is the most robust, tolerating the lowest SNR. QPSK sends two bits per symbol with the same bit error performance per Eb/N0 and double spectral efficiency. 64-QAM sends six bits per symbol using many amplitude and phase levels, so it needs much higher SNR for the same error rate, and is sensitive to noise, nonlinearity and phase noise. Systems adapt modulation to channel quality.", c: ["BPSK is robust with one bit per symbol", "QPSK doubles spectral efficiency", "64-QAM needs high SNR", "Adaptive modulation matches the channel"], k: ["Closer constellation points raise error probability", "Amplifier linearity is critical for QAM"], m: ["Using the highest order modulation regardless of SNR"] },
  { t: "Multipath fading and OFDM", p: "Why does OFDM work well in multipath channels?", d: 3, tp: "communications", i: "Multipath causes frequency-selective fading and intersymbol interference when delay spread approaches the symbol time. OFDM splits the data across many narrow, slow subcarriers whose symbols are much longer than the delay spread, and a cyclic prefix absorbs the remaining echoes, so each subcarrier sees flat fading that a one-tap equaliser can correct. The cost is sensitivity to frequency offset and a high peak-to-average power ratio.", c: ["Multipath creates frequency-selective fading and ISI", "Many narrow subcarriers with long symbols", "Cyclic prefix absorbs delay spread", "Drawbacks: frequency offset sensitivity and high PAPR"], k: ["One-tap equalisation per subcarrier is simple", "Pilots estimate the channel"], m: ["Ignoring the cyclic prefix overhead"] },
  { t: "Error-correcting codes and coding gain", p: "What does forward error correction buy you, and what is the cost?", d: 2, tp: "communications", i: "Adding redundancy lets the receiver detect and correct errors, achieving a target bit error rate at lower Eb/N0, a benefit called coding gain, which translates to less power, longer range or higher throughput. Costs are reduced information rate (code rate below one), more bandwidth or lower throughput, and decoder complexity and latency. Modern codes such as LDPC and turbo codes approach the Shannon limit.", c: ["Redundancy enables correction", "Coding gain lowers the required Eb/N0", "Costs: rate, bandwidth or throughput, complexity and latency", "LDPC and turbo codes approach the limit"], k: ["Interleaving spreads burst errors", "Hard versus soft decoding affects gain"], m: ["Expecting coding to be free"] },
  { t: "Noise figure and cascade receiver sensitivity", p: "Why does the first amplifier's noise figure dominate a receiver, and how do you calculate sensitivity?", d: 3, tp: "communications", tp2: "analog-electronics", i: "Friis's formula gives total noise factor F = F1 + (F2 − 1)/G1 + (F3 − 1)/(G1G2) + …, so later stages are divided by the gain ahead of them, and a low-noise high-gain first stage sets overall noise. Sensitivity is thermal noise floor (−174 dBm/Hz + 10log B) + noise figure + required SNR. Reducing bandwidth or noise figure improves sensitivity.", c: ["Friis noise formula for cascades", "First stage noise figure and gain dominate", "Noise floor −174 dBm/Hz plus 10log B", "Sensitivity adds noise figure and required SNR"], k: ["Filter loss before the amplifier adds directly to noise figure", "Dynamic range trades against sensitivity"], m: ["Putting a lossy filter before the LNA without accounting for it"] },
  { t: "Link layer: collision avoidance in wireless networks", p: "Why can't Wi-Fi use collision detection like Ethernet, and how does CSMA/CA help?", d: 2, tp: "communications", tp2: "networking", i: "A radio cannot transmit and listen on the same channel at once, and hidden nodes cannot hear each other, so collisions cannot be reliably detected. CSMA/CA senses the channel, waits a random backoff before sending, and uses acknowledgements to confirm delivery, with optional RTS/CTS to reserve the medium and reduce hidden-node collisions. Throughput falls as contention rises.", c: ["Radios cannot listen while transmitting", "Hidden nodes cannot sense each other", "Carrier sensing with random backoff and acknowledgements", "RTS/CTS reserves the channel"], k: ["Overhead lowers real throughput below the link rate", "Airtime fairness affects mixed-speed clients"], m: ["Assuming wireless works like switched Ethernet"] },
  { t: "Phase-locked loops in communications", p: "How does a PLL work and what is it used for?", d: 3, tp: "communications", tp2: "control-theory", i: "A PLL compares the phase of a reference with a voltage-controlled oscillator output using a phase detector; the loop filter converts phase error into a control voltage that steers the oscillator until frequency matches and phase error is constant. Uses include clock synthesis and multiplication with a divider in the feedback path, carrier recovery, clock recovery and FM demodulation. Loop bandwidth trades tracking speed against noise filtering.", c: ["Phase detector, loop filter and VCO", "Locks frequency and phase to the reference", "Divider in feedback gives frequency multiplication", "Loop bandwidth trades speed and noise"], k: ["Lock time and jitter depend on loop design", "Reference spurs appear if the filter is inadequate"], m: ["Thinking the PLL only matches phase, not frequency"] },
  { t: "Spread spectrum and CDMA basics", p: "How does direct-sequence spread spectrum provide interference resistance and multiple access?", d: 3, tp: "communications", i: "Each data bit is multiplied by a fast pseudo-noise chip sequence, spreading the signal over a much wider bandwidth with lower power density. The receiver correlates with the same code, collapsing the wanted signal back to narrow bandwidth while narrowband interference and other users' signals, uncorrelated with the code, stay spread and are rejected, giving processing gain equal to the spreading factor. Different codes let multiple users share the band.", c: ["Data multiplied by a chip sequence spreads bandwidth", "Receiver correlates with the code", "Interference stays spread and is rejected", "Processing gain equals the spreading factor"], k: ["Orthogonal codes reduce multi-user interference", "Power control is needed against the near-far problem"], m: ["Thinking spreading increases the data rate"] },
  { t: "Antenna diversity and MIMO gains", p: "What are the two main benefits of multiple antennas, and when does each apply?", d: 3, tp: "communications", tp2: "electromagnetics", i: "Diversity combines signals from antennas with independent fading to reduce the chance that all are in a fade, improving reliability and SNR. Spatial multiplexing sends different data streams on different antennas to multiply capacity in rich scattering with high SNR, requiring antenna spacing and channel conditions that make streams separable. In poor channels or low SNR, beamforming or diversity is better than multiplexing.", c: ["Diversity improves reliability against fading", "Spatial multiplexing multiplies capacity", "Needs rich scattering and high SNR", "Beamforming for low SNR"], k: ["Channel state information guides precoding", "Antenna correlation limits gains"], m: ["Expecting multiplexing gain in a line-of-sight channel"] },
  { t: "Eye diagrams and signal integrity metrics", p: "What does an eye diagram show about a serial link and what closes the eye?", d: 2, tp: "communications", tp2: "hardware-debug", i: "An eye diagram overlays many bit periods on one trace, so a wide open eye indicates clear separation between levels and large timing margin. Eye height shows noise margin and eye width shows timing margin. Closing causes are intersymbol interference from bandwidth limits and reflections, noise, jitter, crosstalk and loss, and equalisation, termination and clean layout reopen it.", c: ["Overlay of bit periods", "Eye height is noise margin and width is timing margin", "ISI, noise, jitter, crosstalk and loss close the eye", "Equalisation and termination reopen it"], k: ["Bit error rate relates to eye opening at the sampler", "Jitter decomposes into random and deterministic parts"], m: ["Judging a link by average amplitude only"] },
  { t: "Choosing between linear and switching power for a sensor board", p: "A low-noise sensor board is powered from 12 V. How would you generate its 3.3 V analog rail?", d: 2, tp: "analog-electronics", tp2: "power-electronics", i: "Use a buck converter for the efficient first step, for example 12 V to about 4 V, followed by a low-noise LDO to 3.3 V, which cleans switching ripple and gives good power supply rejection. This keeps heating low, since the LDO drops only a little voltage, while meeting noise limits. Place and filter carefully: ferrite beads and capacitors, and keep the switcher's loop away from analog traces.", c: ["Efficient buck first stage", "Low-noise LDO post-regulator", "LDO attenuates switching ripple", "Layout and filtering keep noise out"], k: ["Dropout and PSRR at the switching frequency determine the choice", "Heat is limited by the small voltage drop"], m: ["Powering the analog rail directly from a noisy switcher"] },
  { t: "Debugging an unstable switching regulator", p: "A buck converter output rings and the regulator buzzes under load. What is your debugging approach?", d: 3, tp: "power-electronics", tp2: "hardware-debug", i: "Measure the output and switch node with a properly grounded probe, and check the loop with a frequency response analyser or step load: low phase margin shows overshoot and ringing. Check for the usual causes: output capacitor ESR and derating with DC bias changing the loop, inductor saturation under load, layout loops and noisy feedback traces, and compensation values. Fix by adjusting compensation, adding capacitance, improving layout or reducing bandwidth.", c: ["Probe the output and switch node with short ground leads", "Check loop phase margin with step load or a gain-phase test", "Look for inductor saturation, capacitor derating and layout noise", "Adjust compensation and fix the layout"], k: ["Ceramic capacitors lose capacitance with bias voltage", "Subharmonic oscillation appears in peak current mode above 50 percent duty"], m: ["Changing components randomly without measuring the loop"] },
  { t: "Filter capacitor ripple and ESR in a power supply", p: "How do you size the output capacitor of a DC supply for ripple and transient load steps?", d: 2, tp: "power-electronics", i: "Ripple has a capacitive part ΔI·T/(8C)-like term from charge and discharge and an ESR part ΔI·ESR, so choose capacitance and ESR to meet the ripple limit at the switching frequency. For load steps, the capacitor must supply the current difference until the control loop responds, so the allowed droop sets the minimum capacitance, and ESL adds spikes. Account for derating with voltage, temperature and ageing.", c: ["Ripple has capacitive and ESR components", "Meet ripple limit at the switching frequency", "Load step droop sets minimum capacitance", "Derate for voltage, temperature and age"], k: ["Mixed ceramic and bulk capacitors cover frequency ranges", "Control loop bandwidth determines recovery time"], m: ["Sizing from capacitance alone and ignoring ESR"] },
  { t: "Selecting a microcontroller ADC input network", p: "A microcontroller ADC reads a high-impedance sensor and gives noisy, drifting results. What is the likely cause and fix?", d: 2, tp: "analog-electronics", tp2: "embedded-systems", i: "A SAR ADC's sampling capacitor needs charging within the acquisition time. A high source impedance cannot settle it, so the reading depends on the previous channel and loses accuracy. Add a buffer amplifier or a bypass capacitor several times larger than the sample capacitor to act as a charge reservoir, lower the source impedance, increase the sample time and filter noise with an RC low-pass.", c: ["Sampling capacitor must settle within the acquisition time", "High source impedance causes settling errors and crosstalk between channels", "Buffer amplifier or bypass capacitor", "Longer sample time and RC filtering"], k: ["Datasheets specify maximum source impedance", "Multiplexed channels show memory effects"], m: ["Increasing resolution to fix noise"] },
  { t: "Opto-isolation versus digital isolators", p: "Why would you use an isolated interface, and how do optocouplers and digital isolators differ?", d: 2, tp: "circuit-analysis", tp2: "hardware-debug", i: "Isolation breaks ground loops, protects circuits and people from high common-mode voltages and meets safety standards. Optocouplers use an LED and phototransistor, are inexpensive but slow and degrade with age and temperature. Digital isolators use capacitive or magnetic coupling through a barrier, giving higher speed, lower power, better timing and longevity. Each needs an isolated power supply for the far side.", c: ["Isolation breaks ground loops and handles high common-mode voltage", "Optocouplers are slower and age", "Digital isolators are faster and longer lived", "Isolated power for the secondary side"], k: ["Working voltage and creepage define safety ratings", "Common-mode transient immunity matters for motor drives"], m: ["Isolating the signal but not the power"] },
  { t: "Thermal runaway in bipolar transistors and how to prevent it", p: "Why can a bipolar output stage thermally run away, and what circuit measures prevent it?", d: 3, tp: "analog-electronics", tp2: "heat-transfer", i: "Collector current rises with temperature for a fixed base-emitter voltage, which increases dissipation, which raises temperature further, a positive feedback that can destroy the device. Prevention uses emitter degeneration resistors for negative feedback, thermally coupling bias diodes or a Vbe multiplier to the output devices so bias falls as they heat, adequate heat sinking and current limiting.", c: ["Collector current increases with temperature at fixed Vbe", "Positive thermal feedback raises dissipation", "Emitter resistors and thermally tracked bias counter it", "Heat sinking and current limits"], k: ["Paralleling bipolars needs ballast resistors", "MOSFETs have a positive temperature coefficient of resistance, which helps sharing"], m: ["Assuming a bigger heat sink alone solves runaway"] },
];
